import type { TemplateSlug } from "@/templates/registry";

export interface TemplateCatalogEntry {
  id: string;
  slug: TemplateSlug;
  name: string;
  category: string;
  description: string;
  previewImage: string;
  fontFamily: string;
  atsOptimized: boolean;
  premium: boolean;
  layout: string;
}

/** Real static preview paths — generated by scripts/generate-template-previews.mjs */
export const TEMPLATE_PREVIEW_BASE = "/templates";

export function getTemplatePreviewPath(slug: string): string {
  return `${TEMPLATE_PREVIEW_BASE}/${slug}.svg`;
}

