export function getCatalogEntry(slugOrId: string): TemplateCatalogEntry | undefined {
  return TEMPLATE_CATALOG.find((t) => t.slug === slugOrId || t.id === slugOrId);
}

export function resolveTemplateSlug(slugOrId: string | null): string | null {
  if (!slugOrId) return null;
  const entry = getCatalogEntry(slugOrId);
  if (entry) return entry.slug;
  return slugOrId;
}
